+  display:inline-flex;align-items:center;gap:8px;
+  padding:6px 10px;
+  border-radius:999px;
+  border:1px solid var(--stroke);
+  background:rgba(255,255,255,.03);
+  color:var(--muted);
+  font-size:12px;
+  font-weight:700;
+}
+.pill b{color:var(--text)}
+
+.section{padding:26px 0}
+.grid{display:grid;gap:16px}
+.card{
+  border-radius:var(--radius2);
+  background:linear-gradient(180deg, rgba(16,31,46,.72), rgba(11,15,20,.66));
+  border:1px solid var(--stroke);
+  box-shadow:var(--shadow);
+}
+.card-inner{padding:16px}
+
+.h1{font-size:44px;letter-spacing:-.9px;line-height:1.02;margin:0}
+.h2{font-size:18px;margin:0 0 6px 0;letter-spacing:-.2px}
+.muted{color:var(--muted)}
+.faint{color:var(--faint)}
+.small{font-size:12px}
+
+.badge{
+  display:inline-flex;align-items:center;gap:8px;
+  padding:6px 10px;border-radius:999px;
+  border:1px solid rgba(34,211,238,.22);
+  background:rgba(34,211,238,.08);
+  color:rgba(234,240,255,.9);
+  font-weight:800;font-size:12px;
+}
+.dot{width:8px;height:8px;border-radius:999px;background:var(--teal);box-shadow:0 0 0 6px rgba(34,211,238,.12)}
+
+.stat-row{display:flex;gap:10px;flex-wrap:wrap;align-items:center}
+.stat{display:flex;align-items:baseline;gap:10px}
