+.table th{color:var(--faint);font-weight:800;text-transform:uppercase;letter-spacing:.08em}
+.table td{color:var(--text)}
+.table td.mono{font-family:var(--mono)}
+.right{text-align:right}
+.nowrap{white-space:nowrap}
+
+.chg{font-family:var(--mono);font-weight:800}
+.pos{color:var(--green)}
+.neg{color:var(--red)}
+.neu{color:rgba(234,240,255,.72)}
+.pct{
+  display:inline-flex;align-items:center;gap:6px;
