+.pct.pos{border-color:rgba(0,209,122,.26);background:rgba(0,209,122,.08)}
+.pct.neg{border-color:rgba(247,82,95,.28);background:rgba(247,82,95,.08)}
+
+.spark{width:84px;height:28px;border-radius:8px;background:rgba(255,255,255,.03);border:1px solid var(--stroke);display:inline-block;vertical-align:middle}
+
+.split{display:grid;grid-template-columns:1.15fr .85fr;gap:16px}
+
+.footer{padding:28px 0 42px 0;border-top:1px solid var(--stroke);background:rgba(0,0,0,.12)}
