+.footer h4{margin:0 0 10px 0;font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--faint)}
+.footer a{display:block;color:var(--muted);font-size:12px;padding:5px 0}
+.footer a:hover{color:var(--text)}
+.footer-bottom{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:16px;color:var(--faint);font-size:12px}
+
+/* Chart workspace */
+.workspace{display:grid;grid-template-columns: 330px 1fr 360px;gap:12px}
