+.panel .hd .title{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--faint);font-weight:900}
+.panel .bd{padding:12px}
+
+.wl-group{border:1px solid var(--stroke);border-radius:14px;overflow:hidden;background:rgba(255,255,255,.02);margin-bottom:10px}
+.wl-btn{width:100%;display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 12px;border:none;background:transparent;color:var(--text);cursor:pointer}
+.wl-btn:hover{background:rgba(255,255,255,.04)}
+.wl-btn .left{display:flex;align-items:center;gap:10px}
+.wl-btn .tag{font-family:var(--mono);font-size:11px;color:var(--faint)}
+.wl-btn .chev{transition:transform .2s ease;color:var(--faint)}
+.wl-group[data-open="false"] .wl-btn .chev{transform:rotate(-90deg)}
