+.wl-row .sym{font-family:var(--mono);font-weight:900}
+.wl-row .last{font-family:var(--mono)}
+
+.toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
+.toolchip{display:inline-flex;align-items:center;gap:8px;padding:8px 10px;border-radius:12px;border:1px solid var(--stroke);background:rgba(255,255,255,.03);color:var(--muted);font-weight:800;font-size:12px}
