+.chartbox{height:520px;border-radius:16px;border:1px solid var(--stroke);background:radial-gradient(900px 520px at 40% -10%, rgba(41,98,255,.16), transparent 60%), rgba(255,255,255,.02);position:relative;overflow:hidden}
