+.legend-pill{padding:6px 10px;border-radius:999px;border:1px solid var(--stroke);background:rgba(0,0,0,.28);font-family:var(--mono);font-size:11px;color:rgba(234,240,255,.85)}
+
+.kpi-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}
+.kpi{padding:10px 12px;border:1px solid var(--stroke);border-radius:14px;background:rgba(255,255,255,.03)}
+.kpi .k{color:var(--faint);font-size:11px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}
+.kpi .v{margin-top:6px;font-family:var(--mono);font-size:12px;color:var(--text);font-weight:900}
+.kpi .sub{margin-top:6px;color:var(--muted);font-size:12px}
+
+@media (max-width: 1200px){
+  .workspace{grid-template-columns: 320px 1fr;grid-template-rows:auto auto;}
+  .workspace .rightcol{grid-column:1 / -1}
+}
+@media (max-width: 860px){
+  .topbar-inner{flex-wrap:wrap}
+  .search{min-width:0;flex:1}
+  .split{grid-template-columns:1fr}
+  .workspace{grid-template-columns:1fr}
+  .chartbox{height:440px}
+  .footer-grid{grid-template-columns:repeat(2,1fr)}
+  .h1{font-size:34px}
+}
+
*** End Patch
PATCH

